content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  transition: background-color 0.3s, color 0.3s;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 20px;
}

.theme-dark {
  background-color: #121212;
  color: #e0e0e0;
}

.theme-light {
  background-color: #f4f4f9;
  color: #333333;
}

.clock-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 24px;
  letter-spacing: 1px;
}

.clock-wrapper {
  position: relative;
  width: 300px;
  height: 300px;
  margin-bottom: 30px;
}

.theme-dark .clock-face {
  background: #1e1e1e;
  border: 8px solid #333;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px rgba(0, 0, 0, 0.8);
}

.theme-light .clock-face {
  background: #ffffff;
  border: 8px solid #dcdcdc;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1), inset 0 0 15px rgba(0, 0, 0, 0.05);
}

.clock-face {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 50%;
}

.clock-marker {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 2px;
  height: 100%;
  transform-origin: center;
}

.theme-dark .clock-marker.major {
  background-color: #555;
  width: 4px;
}

.theme-light .clock-marker.major {
  background-color: #ccc;
  width: 4px;
}

.theme-dark .clock-marker {
  background-color: #333;
}

.theme-light .clock-marker {
  background-color: #eee;
}

.clock-number {
  position: absolute;
  width: 30px;
  height: 30px;
  text-align: center;
  line-height: 30px;
  font-weight: bold;
  font-size: 1.1rem;
  transform: translate(-50%, -50%);
}

.clock-hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  border-radius: 4px;
  z-index: 10;
}

.hour-hand {
  width: 6px;
  height: 70px;
  background-color: #ff9800;
  transform: translate(-50%, 0);
}

.minute-hand {
  width: 4px;
  height: 100px;
  background-color: #2196f3;
  transform: translate(-50%, 0);
}

.second-hand {
  width: 2px;
  height: 110px;
  background-color: #f44336;
  transform: translate(-50%, 0);
  z-index: 11;
}

.center-dot {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 12px;
  background-color: #f44336;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  z-index: 12;
}

.digital-display {
  font-size: 1.5rem;
  font-family: monospace;
  font-weight: 600;
  margin-bottom: 24px;
  letter-spacing: 2px;
  padding: 8px 16px;
  border-radius: 8px;
}

.theme-dark .digital-display {
  background-color: #1a1a1a;
  border: 1px solid #333;
}

.theme-light .digital-display {
  background-color: #ffffff;
  border: 1px solid #ddd;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.97);
}

.theme-dark .btn {
  background-color: #333;
  color: #fff;
}

.theme-dark .btn:hover {
  background-color: #444;
}

.theme-light .btn {
  background-color: #e0e0e0;
  color: #333;
}

.theme-light .btn:hover {
  background-color: #d0d0d0;
}

export interface ClockTheme {
  id: string;
  name: string;
  bg: string;
  face: string;
  hand: string;
}

export interface ClockSettings {
  showSeconds: boolean;
  showDigital: boolean;
  theme: string;
}

import { useState, useEffect } from 'react';
import './index.css';
import { ClockSettings } from './types';

export default function App() {
  const [time, setTime] = useState<Date>(new Date());
  const [settings, setSettings] = useState<ClockSettings>({
    showSeconds: true,
    showDigital: true,
    theme: 'dark',
  });

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const seconds = time.getSeconds();
  const minutes = time.getMinutes();
  const hours = time.getHours();

  const secondDeg = seconds * 6;
  const minuteDeg = minutes * 6 + seconds * 0.1;
  const hourDeg = (hours % 12) * 30 + minutes * 0.5;

  const toggleTheme = () => {
    setSettings((prev) => ({
      ...prev,
      theme: prev.theme === 'dark' ? 'light' : 'dark',
    }));
  };

  const toggleSeconds = () => {
    setSettings((prev) => ({
      ...prev,
      showSeconds: !prev.showSeconds,
    }));
  };

  const toggleDigital = () => {
    setSettings((prev) => ({
      ...prev,
      showDigital: !prev.showDigital,
    }));
  };

  return (
    <div className={`app-container theme-${settings.theme}`}>
      <h1 className="clock-title">アナログ時計</h1>

      {settings.showDigital && (
        <div className="digital-display">
          {time.toLocaleTimeString()}
        </div>
      )}

      <div className="clock-wrapper">
        <div className="clock-face">
          {[...Array(12)].map((_, i) => {
            const num = i + 1;
            const angle = (num * 30) * (Math.PI / 180);
            const radius = 105;
            const x = 150 + radius * Math.sin(angle);
            const y = 150 - radius * Math.cos(angle);
            return (
              <div
                key={num}
                className="clock-number"
                style={{ top: `${y}px`, left: `${x}px` }}
              >
                {num}
              </div>
            );
          })}

          {[...Array(60)].map((_, i) => {
            const isMajor = i % 5 === 0;
            return (
              <div
                key={i}
                className={`clock-marker ${isMajor ? 'major' : ''}`}
                style={{ transform: `translate(-50%, -50%) rotate(${i * 6}deg)` }}
              />
            );
          })}

          <div
            className="clock-hand hour-hand"
            style={{ transform: `translate(-50%, 0) rotate(${hourDeg}deg)` }}
          />
          <div
            className="clock-hand minute-hand"
            style={{ transform: `translate(-50%, 0) rotate(${minuteDeg}deg)` }}
          />
          {settings.showSeconds && (
            <div
              className="clock-hand second-hand"
              style={{ transform: `translate(-50%, 0) rotate(${secondDeg}deg)` }}
            />
          )}
          <div className="center-dot" />
        </div>
      </div>

      <div className="controls">
        <button className="btn" onClick={toggleTheme}>
          テーマ切替: {settings.theme === 'dark' ? 'ライト' : 'ダーク'}
        </button>
        <button className="btn" onClick={toggleSeconds}>
          秒針: {settings.showSeconds ? '非表示' : '表示'}
        </button>
        <button className="btn" onClick={toggleDigital}>
          デジタル表示: {settings.showDigital ? '非表示' : '表示'}
        </button>
      </div>
    </div>
  );
}
